const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={projects:[],tasks:[],events:[],agents:[],offices:[],resources:[],prompts:[],health:null,currentPlan:null,currentTask:null,selectedProjectId:null,selectedFiles:[],previewRenderKey:'',mapsConfig:null,prospecting:null,prospectingResults:[],prospectingHistory:[],prospectingLeads:[],prospectingFilters:{category:'',region:'',site:'all'}};
const roomKey='pixel-office-rooms-v1',defaultRooms=[{id:'meeting',type:'meeting',name:'Sala de reunião'},{id:'cafe',type:'cafe',name:'Cafeteria'},{id:'rest',type:'rest',name:'Sala de descanso'}];
