function officeSprite(i,kind){const [hair,skin,shirt]=officeColors[i%officeColors.length];return `<svg class="pixel-person ${kind}" viewBox="0 0 32 32" role="img" aria-label="Agente do escritório"><rect x="10" y="3" width="12" height="3" fill="${hair}"/><rect x="7" y="6" width="18" height="8" fill="${hair}"/><rect x="9" y="8" width="14" height="9" fill="${skin}"/><rect x="8" y="12" width="4" height="3" fill="${hair}"/><rect x="20" y="12" width="4" height="3" fill="${hair}"/><rect x="12" y="11" width="2" height="2" fill="#271b2c"/><rect x="19" y="11" width="2" height="2" fill="#271b2c"/><rect x="14" y="15" width="5" height="1" fill="#ae5d65"/><rect x="8" y="18" width="16" height="8" fill="${shirt}"/><rect x="4" y="19" width="5" height="6" fill="${skin}"/><rect x="23" y="19" width="5" height="6" fill="${skin}"/><rect x="9" y="26" width="5" height="3" fill="#33314b"/><rect x="18" y="26" width="5" height="3" fill="#33314b"/></svg>`}
const routines=new Map();let rooms=[],officeOverview=false;try{officeOverview=localStorage.getItem('pixel-office-overview-v1')==='true'}catch{}try{const saved=JSON.parse(localStorage.getItem(roomKey)||'null');rooms=Array.isArray(saved)?saved.filter(r=>r&&typeof r.id==='string'&&typeof r.name==='string'&&Object.hasOwn(roomIcons,r.type)):defaultRooms}catch{rooms=defaultRooms}
