const agentStatus=a=>{const current=tasks.filter(t=>t.agent_id===a.id).sort((x,y)=>new Date(y.created_at)-new Date(x.created_at))[0];if(!current)return{kind:'idle',label:'À DISPOSIÇÃO',task:null,talk:'Pronto para receber um pedido.'};if(current.status==='running')return{kind:'working',label:'TRABALHANDO',task:current,talk:lastAgentMessage(current)||`Trabalhando em: ${current.title}`};if(current.status==='failed')return{kind:'error',label:'PRECISA DE ATENÇÃO',task:current,talk:`Falha: ${(current.error||'abra os detalhes da tarefa').slice(0,96)}`};if(['pending','queued'].includes(current.status))return{kind:'waiting',label:'NA FILA',task:current,talk:health?.codex.available?`Na fila: ${current.title}`:'Aguardando conexão com o Codex.'};if(current.status==='succeeded')return{kind:'done',label:'ENTREGA PRONTA',task:current,talk:lastAgentMessage(current)||'Tarefa concluída; arquivos disponíveis no projeto.'};return{kind:'idle',label:'À DISPOSIÇÃO',task:current,talk:'Aguardando novos pedidos.'}};
